#include <assert.h>
#include "../src/c/query_controller.h"
int main(void){QueryController q;query_controller_init(&q);assert(q.state==QUERY_IDLE&&query_controller_can_sync(&q));assert(query_controller_defer(&q,1)&&q.state==QUERY_DEFERRED);assert(query_controller_deferred_timeout(&q)&&q.state==QUERY_FAILED&&query_controller_can_sync(&q));assert(query_controller_defer(&q,1)&&query_controller_deferred_resume(&q)&&q.state==QUERY_IDLE);assert(query_controller_begin(&q,7));assert(!query_controller_begin(&q,8));assert(query_controller_response(&q,1,0)&&q.state==QUERY_ASSEMBLING);assert(query_controller_response(&q,1,1)&&query_controller_can_sync(&q));assert(query_controller_begin(&q,9));query_controller_fail(&q);assert(query_controller_can_sync(&q));return 0;}
